with cleaned as (select *, concat(channel, '/', status) as channel_status, case when status in ('COMPLETED', 'RETURNED') then 'Priority' else 'Other' end as status_group from orders where store_id is not null and customer_id in (5, 17)) select * from (select customer_id, status, channel, amount from cleaned) src pivot (max(amount) for channel in ('mobile' as mobile, 'web' as web));
